/* Acronumbskull — the acronym bank.
 *
 * Every entry: { w: the acronym, say: how to read it aloud, cat: field it belongs to,
 *                def: what it stands for, note: shown after the guess, lvl: difficulty }
 *
 * What the player judges is the card as a whole: does this acronym stand for that?
 *
 * REAL entries are genuine acronyms with the expansion they actually have.
 * FAKE entries come in two kinds, and the player cannot tell which they are looking
 * at until the answer:
 *   - borrowed: a genuine acronym under an invented expansion. NASA is real; the
 *     National Aeronautics and Space *Agency* is not.
 *   - coined (`coined: true`): the acronym itself does not exist either. Nobody has
 *     ever issued a QRB or filed an HVPT.
 * Either way the note says what is wrong with the card — the true expansion for a
 * borrowed one, what those letters really do stand for (if anything) for a coined one.
 *
 * Real entries also carry `ex` — a sentence using the acronym. Fake ones must not,
 * because the example is what makes the example appear.
 *
 * `say` is the text handed to the speech renderer, not to the screen. Acronyms that
 * are pronounced as words carry the word; ones that are spelled out carry spaced
 * letters, which is the only way a synthesiser reads them one letter at a time.
 *
 * `w` must be plain lowercase letters — it is also the audio filename.
 * The game picks ten entries per round from one difficulty level.
 */

const REAL_ACRONYMS = [
  /* ---------- level 1: acronyms you meet every week ---------- */
  { w: "mri", say: "M R I", cat: "medicine", def: "magnetic resonance imaging", note: "Real. The scanner lines up the hydrogen nuclei in your body with a magnet, then listens to them relax.", ex: "The <em>MRI</em> found the tear that three X-rays had missed.", lvl: 1 },
  { w: "cpr", say: "C P R", cat: "medicine", def: "cardiopulmonary resuscitation", note: "Real. Chest compressions plus rescue breaths; the modern guidance leans heavily on the compressions.", ex: "Two passengers took turns at <em>CPR</em> until the ambulance arrived.", lvl: 1 },
  { w: "suv", say: "S U V", cat: "transport", def: "sport utility vehicle", note: "Real. An American coinage from the 1980s for a car built on a light truck frame.", ex: "The car park had been redrawn twice to fit the new generation of <em>SUVs</em>.", lvl: 1 },
  { w: "abs", say: "A- B S", cat: "transport", def: "anti-lock braking system", note: "Real, from the German <em>Antiblockiersystem</em>. It pumps the brakes faster than any foot can.", ex: "You feel the <em>ABS</em> shudder through the pedal and you let it do its job.", lvl: 1 },
  { w: "dna", say: "D N A-", cat: "science", def: "deoxyribonucleic acid", note: "Real. Named for the sugar in its backbone, deoxyribose, which is ribose minus one oxygen.", ex: "A single hair left in the car carried enough <em>DNA</em> to close the case.", lvl: 1 },
  { w: "tnt", say: "T N T", cat: "science", def: "trinitrotoluene", note: "Real. Three nitro groups bolted onto toluene. It was a yellow dye for thirty years before anyone detonated it.", ex: "The quarry brought down the whole face with eight tonnes of <em>TNT</em>.", lvl: 1 },
  { w: "atm", say: "A- T M", cat: "finance", def: "automated teller machine", note: "Real. Britain called the first one a cash dispenser; the American name won.", ex: "The only <em>ATM</em> in the village charges two pounds a withdrawal.", lvl: 1 },
  { w: "dvd", say: "D V D", cat: "media", def: "digital versatile disc", note: "Real, and fought over: the consortium could not agree between \"versatile\" and \"video\", so the official line became that DVD stands for nothing at all.", ex: "A shoebox of <em>DVDs</em> nobody has a player for.", lvl: 1 },
  { w: "bbc", say: "B B C", cat: "media", def: "British Broadcasting Corporation", note: "Real. It began in 1922 as the British Broadcasting Company and was made a corporation five years later.", ex: "The <em>BBC</em> broke the news forty minutes before anyone else.", lvl: 1 },
  { w: "sms", say: "S M S", cat: "telecoms", def: "short message service", note: "Real. The 160-character limit came from what would fit in the spare signalling capacity of a GSM network.", ex: "A two-word <em>SMS</em> at 3am is rarely good news.", lvl: 1 },
  { w: "sim", say: "S I M", cat: "telecoms", def: "subscriber identity module", note: "Real. The card is the subscriber; the handset is just a radio.", ex: "She swapped the <em>SIM</em> into an old phone and carried on.", lvl: 1 },
  { w: "html", say: "H T M L", cat: "computing", def: "hypertext markup language", note: "Real. Tim Berners-Lee's 1991 sketch had twenty tags in it.", ex: "The whole site is one page of hand-written <em>HTML</em>.", lvl: 1 },
  { w: "jpeg", say: "jay peg", cat: "computing", def: "Joint Photographic Experts Group", note: "Real, and it names the committee rather than the format — the file is named after the people who agreed it.", ex: "Every time you re-save a <em>JPEG</em> it loses a little more of itself.", lvl: 1 },
  { w: "awol", say: "ay wall", cat: "military", def: "absent without leave", note: "Real, and old: it appears in American Civil War records, where offenders wore a placard reading A.W.O.L.", ex: "Two of the platoon were <em>AWOL</em> by the second morning.", lvl: 1 },
  { w: "nato", say: "nay toe", cat: "military", def: "North Atlantic Treaty Organization", note: "Real, founded 1949. Twelve members then, thirty-two now.", ex: "The exercise put four <em>NATO</em> navies in the same stretch of sea.", lvl: 1 },
  { w: "hvac", say: "H VAC", cat: "engineering", def: "heating, ventilation and air conditioning", note: "Real, and the reason a building's roof looks the way it does.", ex: "Half the budget went on <em>HVAC</em> before a single desk was bought.", lvl: 1 },
  { w: "scuba", say: "scuba", cat: "marine", def: "self-contained underwater breathing apparatus", note: "Real. Coined in 1952 by Christian Lambertsen for the US military rebreather he had designed.", ex: "He learned to <em>scuba</em> dive at forty and never got over it.", lvl: 1 },
  { w: "sonar", say: "sonar", cat: "marine", def: "sound navigation and ranging", note: "Real, built as an American answer to the British word ASDIC.", ex: "The <em>sonar</em> picked up the wreck sitting upright in ninety metres.", lvl: 1 },
  { w: "radar", say: "raydar", cat: "aviation", def: "radio detection and ranging", note: "Real, coined by the US Navy in 1940. It reads the same backwards, which was not an accident.", ex: "The storm showed on the <em>radar</em> as a wall of red.", lvl: 1 },
  { w: "unesco", say: "you nesco", cat: "government", def: "United Nations Educational, Scientific and Cultural Organization", note: "Real, founded 1945 — the body behind the World Heritage list.", ex: "The whole valley was given <em>UNESCO</em> protection in 1987.", lvl: 1 },
  { w: "nasdaq", say: "nazdak", cat: "finance", def: "National Association of Securities Dealers Automated Quotations", note: "Real. It opened in 1971 as a screen full of prices with no trading floor at all.", ex: "The <em>NASDAQ</em> closed down two per cent on the news.", lvl: 1 },
  { w: "qantas", say: "kwontas", cat: "aviation", def: "Queensland and Northern Territory Aerial Services", note: "Real, which is why it has no U after the Q. Founded 1920 to fly mail across the outback.", ex: "<em>Qantas</em> has been flying under that name since 1920.", lvl: 1 },
  { w: "captcha", say: "captcha", cat: "computing", def: "completely automated public Turing test to tell computers and humans apart", note: "Real, coined at Carnegie Mellon in 2003, and named for Alan Turing's test.", ex: "The <em>CAPTCHA</em> asked him to find the traffic lights nine times.", lvl: 1 },

  /* ---------- level 2: acronyms you half-know ---------- */
  { w: "zip", say: "zip", cat: "government", def: "zone improvement plan", note: "Real. The US Post Office launched it in 1963 with a cartoon mascot called Mr ZIP.", ex: "Write the <em>ZIP</em> code clearly or it goes to the wrong state.", lvl: 2 },
  { w: "paye", say: "P A- Y E", cat: "finance", def: "pay as you earn", note: "Real. Britain's income tax has been deducted at source under this name since 1944.", ex: "Everything comes off under <em>PAYE</em> before he sees a penny.", lvl: 2 },
  { w: "bios", say: "by oss", cat: "computing", def: "basic input/output system", note: "Real, from CP/M in the 1970s. It is the code that runs before the operating system exists.", ex: "You have to get into the <em>BIOS</em> to change the boot order.", lvl: 2 },
  { w: "modem", say: "moe dem", cat: "telecoms", def: "modulator-demodulator", note: "Real. It turns bits into a noise the phone line will carry, and back again.", ex: "The <em>modem</em> made that noise for about eleven seconds and then you were online.", lvl: 2 },
  { w: "nimby", say: "nimby", cat: "government", def: "not in my back yard", note: "Real, coined around 1980 and now in every dictionary, usually as a noun for the person.", ex: "The wind farm ran into the usual <em>NIMBY</em> objections.", lvl: 2 },
  { w: "snafu", say: "sna foo", cat: "military", def: "situation normal, all fouled up", note: "Real US Army slang from 1941. The original F stood for something less printable.", ex: "The convoy schedule was the usual <em>SNAFU</em>.", lvl: 2 },
  { w: "anzac", say: "an zac", cat: "military", def: "Australian and New Zealand Army Corps", note: "Real, coined in Egypt in 1914 as a cable address and now a national day.", ex: "The <em>ANZAC</em> landings at Gallipoli began on 25 April 1915.", lvl: 2 },
  { w: "naafi", say: "naffy", cat: "military", def: "Navy, Army and Air Force Institutes", note: "Real. Since 1920 it has run the canteens, shops and bars on British bases.", ex: "They met in the <em>NAAFI</em> queue and married a year later.", lvl: 2 },
  { w: "cobol", say: "co ball", cat: "computing", def: "common business-oriented language", note: "Real, designed in 1959 by a committee that included Grace Hopper. Banks still run on it.", ex: "The payroll system is sixty thousand lines of <em>COBOL</em>.", lvl: 2 },
  { w: "quango", say: "kwang go", cat: "government", def: "quasi-autonomous non-governmental organisation", note: "Real, coined about 1970 by the political scientist Anthony Barker.", ex: "The review promised a bonfire of the <em>quangos</em> and quietly created two more.", lvl: 2 },
  { w: "gulag", say: "goo lag", cat: "government", def: "Glavnoye Upravleniye Lagerey, the chief administration of camps", note: "Real, and Russian: the word named the bureau that ran the camps before it named the camps.", ex: "He spent eleven years in the <em>gulag</em> and wrote none of it down.", lvl: 2 },
  { w: "quasar", say: "kway zar", cat: "science", def: "quasi-stellar radio source", note: "Real, coined in 1964. They looked like stars and roared on the radio, hence the hedge in the name.", ex: "The <em>quasar</em> is twelve billion light years out and still outshines its galaxy.", lvl: 2 },
  { w: "sample", say: "sample", cat: "medicine", def: "signs, allergies, medications, past history, last intake, events", note: "Real, and drilled into every ambulance crew: the six questions you ask before anything else.", ex: "He took a <em>SAMPLE</em> history while the stretcher was being fetched.", lvl: 2 },
  { w: "mirv", say: "murv", cat: "military", def: "multiple independently targetable re-entry vehicle", note: "Real. One missile, several warheads, each aimed somewhere different — the reason arms control got difficult.", ex: "A single <em>MIRV</em> bus could carry ten warheads to ten cities.", lvl: 2 },
  { w: "asbo", say: "az bo", cat: "policing", def: "anti-social behaviour order", note: "Real. A British civil order introduced in 1998 and abolished in 2014, though the word outlived it.", ex: "He collected an <em>ASBO</em> at sixteen and wore it like a medal.", lvl: 2 },
  { w: "fortran", say: "for tran", cat: "computing", def: "formula translation", note: "Real, from IBM in 1957 — the first widely used high-level language, and still doing the heavy numerical work.", ex: "The climate model has <em>FORTRAN</em> in it older than most of the team.", lvl: 2 },
  { w: "pelican", say: "pelican", cat: "transport", def: "pedestrian light controlled crossing", note: "Real. Britain named its crossings after birds — pelican, puffin, toucan — and only the puffin is a proper acronym too.", ex: "There is a <em>pelican</em> crossing outside the school gates.", lvl: 2 },
  { w: "nabisco", say: "na bisco", cat: "business", def: "National Biscuit Company", note: "Real. The nickname was made official in 1941, partly to stop people confusing N.B.C. with the broadcaster.", ex: "<em>Nabisco</em> has been printed on biscuit packets since 1901.", lvl: 2 },
  { w: "comecon", say: "comme econ", cat: "government", def: "Council for Mutual Economic Assistance", note: "Real. The Eastern Bloc's answer to the Marshall Plan, wound up in 1991.", ex: "Trade inside <em>Comecon</em> was settled in transferable roubles nobody else would take.", lvl: 2 },
  { w: "navstar", say: "nav star", cat: "space", def: "navigation satellite timing and ranging", note: "Real. The full name of the system is NAVSTAR GPS; almost everyone drops the first half.", ex: "The first <em>NAVSTAR</em> satellite went up in 1978.", lvl: 2 },
  { w: "arpanet", say: "arpa net", cat: "telecoms", def: "Advanced Research Projects Agency Network", note: "Real. Four nodes in 1969, and the ancestor of everything you are reading this on.", ex: "The first <em>ARPANET</em> message crashed after two letters.", lvl: 2 },
  { w: "oracle", say: "oracle", cat: "media", def: "Optional Reception of Announcements by Coded Line Electronics", note: "Real, and a backronym built to fit the word: ITV's teletext service from 1978 to 1992.", ex: "You waited ninety seconds for <em>ORACLE</em> to cycle round to the football scores.", lvl: 2 },
  { w: "sigint", say: "sig int", cat: "military", def: "signals intelligence", note: "Real, and one of a family: COMINT for communications, ELINT for electronics, HUMINT for people.", ex: "The whole picture came from <em>SIGINT</em>, not from anyone on the ground.", lvl: 2 },

  /* ---------- level 3: acronyms almost nobody has met ---------- */
  { w: "lem", say: "lem", cat: "space", def: "lunar excursion module", note: "Real. NASA later dropped the \"excursion\" and called it the LM, but the crews never stopped saying lem.", ex: "The <em>LEM</em> had less computing power than a modern doorbell.", lvl: 3 },
  { w: "iff", say: "I F F", cat: "aviation", def: "identification, friend or foe", note: "Real, and in service since 1939 — the transponder that answers a radar's challenge.", ex: "Without a working <em>IFF</em> you are just a contact on someone's screen.", lvl: 3 },
  { w: "vhf", say: "V H F", cat: "telecoms", def: "very high frequency", note: "Real, and one band of a whole ladder — LF, MF, HF, VHF, UHF, SHF, EHF.", ex: "Air traffic control still runs on <em>VHF</em> voice, in the clear.", lvl: 3 },
  { w: "spqr", say: "S P Q R", cat: "government", def: "Senatus Populusque Romanus, the senate and people of Rome", note: "Real, and still stamped on the drain covers of modern Rome.", ex: "The standard carried <em>SPQR</em> in letters a foot high.", lvl: 3 },
  { w: "squid", say: "squid", cat: "science", def: "superconducting quantum interference device", note: "Real, and the most sensitive magnetometer there is — it will read the magnetic field of a thought.", ex: "The <em>SQUID</em> array picked up brain activity through the skull.", lvl: 3 },
  { w: "lidar", say: "lie dar", cat: "science", def: "light detection and ranging", note: "Real, built on the pattern of radar. Archaeologists use it to strip forests off a landscape.", ex: "<em>LIDAR</em> found a whole Mayan city under the canopy.", lvl: 3 },
  { w: "maser", say: "may zer", cat: "science", def: "microwave amplification by stimulated emission of radiation", note: "Real, and first: the maser came in 1953, the laser five years later.", ex: "The <em>maser</em> in the ground station amplifies a whisper from Voyager.", lvl: 3 },
  { w: "ernie", say: "ernie", cat: "finance", def: "electronic random number indicator equipment", note: "Real. Britain's Premium Bonds draw has been made by a machine of this name since 1957; the first was built by Tommy Flowers of Colossus fame.", ex: "<em>ERNIE</em> picks two million winners a month and has never been accused of a pattern.", lvl: 3 },
  { w: "scart", say: "scart", cat: "engineering", def: "Syndicat des Constructeurs d'Appareils Radiorecepteurs et Televiseurs", note: "Real, and French: the connector is named after the trade body that specified it in the 1970s.", ex: "Everything in the loft has a <em>SCART</em> socket and nothing has a SCART lead.", lvl: 3 },
  { w: "posslq", say: "possel cue", cat: "government", def: "person of the opposite sex sharing living quarters", note: "Real. The US Census Bureau coined it in the 1970s to count couples who would not call themselves one.", ex: "For one census the country was full of <em>POSSLQs</em>, and then the form changed.", lvl: 3 },
  { w: "wysiwyg", say: "wizzy wig", cat: "computing", def: "what you see is what you get", note: "Real, from a 1970s catchphrase, and the whole promise of the first page-layout software.", ex: "The editor is <em>WYSIWYG</em> until you open the file somewhere else.", lvl: 3 },
  { w: "norwich", say: "norridge", cat: "military", def: "knickers off ready when I come home", note: "Real. British servicemen wrote it on the back of envelopes in the Second World War, alongside BURMA and SWALK.", ex: "The censor let <em>NORWICH</em> through because it looked like a postmark.", lvl: 3 },
  { w: "holland", say: "holland", cat: "military", def: "hope our love lasts and never dies", note: "Real, and from the same wartime envelope code as NORWICH — the point was that a censor could not object to a place name.", ex: "Every letter she kept has <em>HOLLAND</em> pencilled on the flap.", lvl: 3 },
  { w: "autovon", say: "auto von", cat: "telecoms", def: "automatic voice network", note: "Real. The American military's own worldwide telephone system, built from 1963 and retired in the 1990s.", ex: "An <em>AUTOVON</em> handset had four extra keys for precedence, up to Flash Override.", lvl: 3 },
  { w: "lantirn", say: "lan turn", cat: "aviation", def: "low altitude navigation and targeting infrared for night", note: "Real, and a pair of pods rather than one box: one navigates, one aims.", ex: "With <em>LANTIRN</em> the aircraft could fly the valley in the dark.", lvl: 3 },
  { w: "techint", say: "teck int", cat: "military", def: "technical intelligence", note: "Real, and the branch that takes captured equipment apart to see how it works.", ex: "The recovered drone went straight to <em>TECHINT</em>.", lvl: 3 },
  { w: "multics", say: "multics", cat: "computing", def: "multiplexed information and computing service", note: "Real, and the project Unix was a reaction against — the name Unix was a pun on it.", ex: "<em>Multics</em> had rings of protection when everyone else had none.", lvl: 3 },
  { w: "medlars", say: "med lars", cat: "medicine", def: "medical literature analysis and retrieval system", note: "Real. The 1964 computer index of medical papers that eventually became PubMed.", ex: "A <em>MEDLARS</em> search took a librarian, a form and a fortnight.", lvl: 3 },
  { w: "champus", say: "champus", cat: "medicine", def: "civilian health and medical program of the uniformed services", note: "Real, the American forces' health scheme from 1966 until it became TRICARE in the 1990s.", ex: "Her mother's operation was paid for under <em>CHAMPUS</em>.", lvl: 3 },
  { w: "reforger", say: "re forger", cat: "military", def: "return of forces to Germany", note: "Real. An annual Cold War exercise in flying an American army across the Atlantic before anyone else could.", ex: "<em>REFORGER</em> moved a hundred thousand troops in a fortnight.", lvl: 3 },
  { w: "loran", say: "lore an", cat: "marine", def: "long range navigation", note: "Real, wartime American, and still switched on in places as a backup for when GPS is jammed.", ex: "Before satellites, an Atlantic crossing was plotted on <em>LORAN</em> lines.", lvl: 3 },
  { w: "ebcdic", say: "ebb see dick", cat: "computing", def: "extended binary coded decimal interchange code", note: "Real, IBM's rival to ASCII, and the reason some mainframe data still arrives looking like gibberish.", ex: "The tape was <em>EBCDIC</em>, so nothing on it read as text.", lvl: 3 },
  { w: "unicef", say: "you nee sef", cat: "government", def: "United Nations International Children's Emergency Fund", note: "Real. The emergency was meant to be temporary, so in 1953 the name was shortened to United Nations Children's Fund — and the old initials were kept because everyone knew them.", ex: "<em>UNICEF</em> ran the vaccination programme across the whole province.", lvl: 1 },
  { w: "gestapo", say: "gestapo", cat: "policing", def: "Geheime Staatspolizei, the secret state police", note: "Real, and German: a clerk in the Berlin post office is usually credited with the abbreviation, because the full name would not fit on a franking stamp.", ex: "Two men from the <em>Gestapo</em> were waiting in the hall.", lvl: 2 },
  { w: "benelux", say: "benny lux", cat: "government", def: "Belgium, the Netherlands and Luxembourg", note: "Real. A customs union signed in 1944 by three governments then in exile, and a working rehearsal for the EU.", ex: "The three <em>Benelux</em> countries dropped their border checks decades before their neighbours.", lvl: 2 },
  { w: "shaef", say: "shafe", cat: "military", def: "Supreme Headquarters Allied Expeditionary Force", note: "Real. Eisenhower's command for the invasion of Europe, run from a requisitioned school in Bushy Park.", ex: "The order came down from <em>SHAEF</em> on the evening of 5 June.", lvl: 3 },

  /* ---------- level 1, second batch ---------- */
  { w: "usb", say: "U S B", cat: "computing", def: "universal serial bus", note: "Real. The universal part took three tries and two decades, and the plug still goes in the wrong way up.", ex: "There is a drawer in every house with eleven <em>USB</em> cables and no charger.", lvl: 1 },
  { w: "pdf", say: "P D F", cat: "computing", def: "portable document format", note: "Real. Adobe opened the format up in 2008, which is why everything can now make one.", ex: "They sent the contract as a <em>PDF</em> nobody could edit.", lvl: 1 },
  { w: "lcd", say: "L C D", cat: "engineering", def: "liquid crystal display", note: "Real. The crystals really are liquid — a phase of matter that flows like a liquid but lines up like a solid.", ex: "The calculator had a four-line <em>LCD</em> and ran for a decade on one battery.", lvl: 1 },
  { w: "cnc", say: "C N C", cat: "engineering", def: "computer numerical control", note: "Real. It replaced plain NC, numerical control, which was driven by punched tape.", ex: "A <em>CNC</em> mill will cut the same part four hundred times without complaint.", lvl: 1 },
  { w: "led", say: "L E D", cat: "engineering", def: "light-emitting diode", note: "Real. Red ones arrived in 1962; the blue one that made white light possible took another thirty years and won a Nobel Prize.", ex: "The whole street was relit with <em>LED</em> lamps in a fortnight.", lvl: 1 },
  { w: "hgv", say: "H G V", cat: "transport", def: "heavy goods vehicle", note: "Real, and British: the American equivalent is a commercial motor vehicle, which is less blunt.", ex: "The bridge has an <em>HGV</em> weight limit that half the sat-navs ignore.", lvl: 1 },
  { w: "hiv", say: "H I V", cat: "medicine", def: "human immunodeficiency virus", note: "Real. The name was agreed in 1986 to settle a row between two laboratories that had each called it something else.", ex: "<em>HIV</em> went from a death sentence to a daily tablet inside twenty years.", lvl: 1 },
  { w: "spf", say: "S P F", cat: "medicine", def: "sun protection factor", note: "Real, and a multiplier rather than a score: factor 30 means thirty times as long before you burn.", ex: "Anything under <em>SPF</em> 30 is optimism rather than protection.", lvl: 1 },
  { w: "asap", say: "A- S A- P", cat: "business", def: "as soon as possible", note: "Real, and military before it was corporate — it turns up in US Army signals traffic in the 1950s.", ex: "Every email that says <em>ASAP</em> means something different to the person who sent it.", lvl: 1 },
  { w: "rsvp", say: "R S V P", cat: "business", def: "repondez s'il vous plait", note: "Real, and French: \"reply, if you please\". English took the initials and left the manners behind.", ex: "The invitation asked you to <em>RSVP</em> by the tenth and nobody did.", lvl: 1 },
  { w: "aids", say: "aids", cat: "medicine", def: "acquired immune deficiency syndrome", note: "Real. The name was settled in 1982, replacing a string of far worse ones the press had been using.", ex: "The first <em>AIDS</em> cases were reported in June 1981.", lvl: 1 },
  { w: "laser", say: "laser", cat: "science", def: "light amplification by stimulated emission of radiation", note: "Real, and built on the pattern of MASER, which came first. One of its inventors called it a solution looking for a problem.", ex: "A supermarket checkout is the most common <em>laser</em> most people ever meet.", lvl: 1 },
  { w: "ofsted", say: "off sted", cat: "government", def: "Office for Standards in Education", note: "Real, and the eldest of a whole British family — Ofcom, Ofgem, Ofwat, Ofqual.", ex: "Two days' notice of an <em>Ofsted</em> inspection is enough to empty a staffroom.", lvl: 1 },

  /* ---------- level 2, second batch ---------- */
  { w: "gdp", say: "G D P", cat: "finance", def: "gross domestic product", note: "Real, and invented for a purpose: Simon Kuznets built it in the 1930s to measure a depression, and warned against using it to measure welfare.", ex: "Two quarters of falling <em>GDP</em> is the rule-of-thumb definition of a recession.", lvl: 2 },
  { w: "hrt", say: "H R T", cat: "medicine", def: "hormone replacement therapy", note: "Real, and forty years of argument about whether the benefits outweigh the risks.", ex: "She went back on <em>HRT</em> and slept through the night for the first time in a year.", lvl: 2 },
  { w: "gsm", say: "G S M", cat: "telecoms", def: "Global System for Mobile Communications", note: "Real, and renamed: it began as Groupe Special Mobile, the French committee that drew it up.", ex: "An old <em>GSM</em> handset will still find a signal where nothing else can.", lvl: 2 },
  { w: "opec", say: "oh peck", cat: "government", def: "Organization of the Petroleum Exporting Countries", note: "Real, founded in Baghdad in 1960 by five countries tired of the price being set somewhere else.", ex: "An <em>OPEC</em> meeting can move the price at every filling station in Europe.", lvl: 2 },
  { w: "sars", say: "sars", cat: "medicine", def: "severe acute respiratory syndrome", note: "Real, named by the World Health Organization in 2003 — and the reason the 2019 coronavirus was called SARS-CoV-2.", ex: "<em>SARS</em> was contained in eight months, which at the time seemed unremarkable.", lvl: 2 },
  { w: "isbn", say: "I S B N", cat: "business", def: "International Standard Book Number", note: "Real, and invented for W H Smith in 1966 so that a warehouse could tell two editions apart.", ex: "Every edition gets its own <em>ISBN</em>, including the paperback.", lvl: 2 },
  { w: "taser", say: "tay zer", cat: "policing", def: "Thomas A. Swift's electric rifle", note: "Real, and a tribute: the inventor named it after a boys' adventure novel, <em>Tom Swift and His Electric Rifle</em>, and put the A in to make it sayable.", ex: "The officer drew a <em>Taser</em> rather than a firearm.", lvl: 2 },
  { w: "ascii", say: "askey", cat: "computing", def: "American Standard Code for Information Interchange", note: "Real, agreed in 1963, and still the first 128 characters of almost everything you read on a screen.", ex: "Save it as plain <em>ASCII</em> and it will open anywhere.", lvl: 2 },
  { w: "oxfam", say: "ox fam", cat: "government", def: "Oxford Committee for Famine Relief", note: "Real. It was founded in 1942 to get food past the Allied blockade and into occupied Greece.", ex: "The high street has two charity shops and one of them is <em>Oxfam</em>.", lvl: 2 },
  { w: "napalm", say: "nay palm", cat: "science", def: "naphthenic and palmitic acids", note: "Real, and chemical: the aluminium salts of those two acids are what thickened the petrol. Devised at Harvard in 1942.", ex: "<em>Napalm</em> began as a thickening agent, which is the least of what it became.", lvl: 2 },
  { w: "yuppie", say: "yuppie", cat: "business", def: "young urban professional", note: "Real, coined about 1980 and worn out by 1990. Its relatives — dinky, buppie, guppie — did not last as long.", ex: "The bar was full of <em>yuppies</em> ordering drinks nobody had heard of.", lvl: 2 },
  { w: "simple", say: "simple", cat: "computing", def: "SIP for Instant Messaging and Presence Leveraging Extensions", note: "Real, and an IETF standard, which is the sort of place a name like this survives.", ex: "The messaging gateway spoke <em>SIMPLE</em> at one end and something proprietary at the other.", lvl: 2 },
  { w: "medevac", say: "med evac", cat: "medicine", def: "medical evacuation", note: "Real, out of Korea and Vietnam, where the helicopter turned a stretcher party into a flight.", ex: "The climber was <em>medevaced</em> off the ridge before dark.", lvl: 2 },

  /* ---------- level 3, second batch ---------- */
  { w: "ecm", say: "E C M", cat: "military", def: "electronic countermeasures", note: "Real. Jamming, spoofing and chaff all sit under it — and ECCM is the counter to the counter.", ex: "The aircraft went in under an <em>ECM</em> blanket that made the radar useless.", lvl: 3 },
  { w: "swot", say: "swot", cat: "business", def: "strengths, weaknesses, opportunities and threats", note: "Real, from Stanford in the 1960s, and the four boxes drawn on more whiteboards than any other diagram.", ex: "The away day produced a <em>SWOT</em> analysis and nothing else.", lvl: 3 },
  { w: "sofar", say: "so far", cat: "marine", def: "sound fixing and ranging", note: "Real. A layer of ocean where sound is trapped and carries for thousands of miles, found by dropping explosives into it in 1944.", ex: "A charge set off in the <em>SOFAR</em> channel can be heard a continent away.", lvl: 3 },
  { w: "edsac", say: "ed sac", cat: "computing", def: "Electronic Delay Storage Automatic Calculator", note: "Real. Cambridge, 1949, and the first stored-program computer to do useful work for anyone who asked.", ex: "<em>EDSAC</em> kept its memory as sound waves travelling down tubes of mercury.", lvl: 3 },
  { w: "jovial", say: "jovial", cat: "computing", def: "Jules' Own Version of the International Algorithmic Language", note: "Real, and named after Jules Schwartz, who wrote it. He always said the name started as a joke.", ex: "Some air defence systems were still running <em>JOVIAL</em> in the 2000s.", lvl: 3 },
  { w: "snobol", say: "sno bol", cat: "computing", def: "string oriented symbolic language", note: "Real, from Bell Labs in 1962 — and the expansion came after the name, which itself came from not having a snowball's chance.", ex: "<em>SNOBOL</em> could match patterns in text that other languages of the day could not see.", lvl: 3 },
  { w: "vortac", say: "vor tac", cat: "aviation", def: "VHF omnidirectional range and tactical air navigation", note: "Real, and two beacons on one mast: the civil half gives a bearing, the military half gives bearing and distance.", ex: "Airways are still strung between <em>VORTAC</em> stations on the chart.", lvl: 3 },
  { w: "saclant", say: "sack lant", cat: "military", def: "Supreme Allied Commander Atlantic", note: "Real. NATO's Atlantic half from 1952 until 2003, run from Norfolk, Virginia.", ex: "<em>SACLANT</em> was always an American admiral, by an arrangement nobody wrote down.", lvl: 3 },
  { w: "photint", say: "photo int", cat: "military", def: "photographic intelligence", note: "Real, and one of the -INT family alongside SIGINT and HUMINT. It became IMINT once the pictures stopped being photographs.", ex: "The whole case rested on a single frame of <em>PHOTINT</em>.", lvl: 3 },
  { w: "interpol", say: "interpol", cat: "policing", def: "International Criminal Police Organization", note: "Real, and the cable address came first: the organisation took the telegraphic name it had been using since 1946.", ex: "An <em>Interpol</em> red notice is a request, not a warrant.", lvl: 3 },
  { w: "conelrad", say: "conel rad", cat: "media", def: "control of electromagnetic radiation", note: "Real. American radios of the 1950s had little civil-defence triangles printed at 640 and 1240 on the dial for it.", ex: "Under <em>CONELRAD</em> every station would have shut down but two frequencies.", lvl: 3 }
];


const FAKE_ACRONYMS = [
  /* ---------- level 1: real acronyms, invented meanings ---------- */
  { w: "gps", say: "G P S", cat: "transport", def: "global positioning satellite", note: "Fake. GPS stands for Global Positioning System. The satellites are the hardware; the system is the thing you are using.", lvl: 1 },
  { w: "url", say: "U R L", cat: "computing", def: "universal resource locator", note: "Fake. URL stands for Uniform Resource Locator. Uniform because every scheme — http, ftp, mailto — has to be written the same way.", lvl: 1 },
  { w: "dns", say: "D N S", cat: "computing", def: "domain naming service", note: "Fake. DNS stands for Domain Name System. A system, not a service: the name resolution is distributed across the whole internet.", lvl: 1 },
  { w: "ftp", say: "F T P", cat: "computing", def: "file transport protocol", note: "Fake. FTP stands for File Transfer Protocol. Transfer, and it dates from 1971, four years before Microsoft existed.", lvl: 1 },
  { w: "tcp", say: "T C P", cat: "computing", def: "transfer control protocol", note: "Fake. TCP stands for Transmission Control Protocol. Transmission, and it is half of TCP/IP; the IP half handles the addressing.", lvl: 1 },
  { w: "gif", say: "gif", cat: "computing", def: "graphic image format", note: "Fake. GIF stands for Graphics Interchange Format. Interchange, because CompuServe built it to move images between different machines.", lvl: 1 },
  { w: "ram", say: "ram", cat: "computing", def: "rapid access memory", note: "Fake. RAM stands for random-access memory. Random access: any byte can be reached as fast as any other, which tape could not do.", lvl: 1 },
  { w: "cpu", say: "C P U", cat: "computing", def: "computer processing unit", note: "Fake. CPU stands for central processing unit. Central, because it was the one part of a mainframe everything else reported to.", lvl: 1 },
  { w: "fbi", say: "F B I", cat: "policing", def: "Federal Bureau of Intelligence", note: "Fake. FBI stands for Federal Bureau of Investigation — <em>investigation</em>. The intelligence side of American government is the CIA's job.", lvl: 1 },
  { w: "cat", say: "cat", cat: "medicine", def: "computed anatomical tomography", note: "Fake. CAT stands for computed axial tomography — <em>axial</em>. The scanner turns around the axis of the body, taking slices as it goes.", lvl: 1 },
  { w: "rpm", say: "R P M", cat: "engineering", def: "rotations per minute", note: "Fake. RPM stands for revolutions per minute — <em>revolutions</em>. An engine revolves; nothing rotates per minute in the manual.", lvl: 1 },
  { w: "pet", say: "pet", cat: "medicine", def: "positron energy tomography", note: "Fake. PET stands for positron emission tomography — <em>emission</em>. The tracer emits the positrons; the scanner only listens.", lvl: 1 },
  { w: "faq", say: "F A- Q", cat: "computing", def: "formally asked questions", note: "Fake. FAQ stands for frequently asked questions — <em>frequently</em>. The questions are not asked formally; they are asked over and over.", lvl: 1 },
  { w: "ufo", say: "U F O", cat: "space", def: "unclassified flying object", note: "Fake. UFO stands for unidentified flying object. Unidentified, which is the whole point: nobody has identified it.", lvl: 1 },
  { w: "lpg", say: "L P G", cat: "transport", def: "liquid petroleum gas", note: "Fake. LPG stands for liquefied petroleum gas — <em>liquefied</em>. It is a gas that has been squeezed into a liquid, which is the whole trick.", lvl: 1 },
  { w: "bmi", say: "B M I", cat: "medicine", def: "basal mass index", note: "Fake. BMI stands for body mass index. Body mass, weight over height squared; the basal metabolic rate is a different number.", lvl: 1 },
  { w: "icu", say: "I C U", cat: "medicine", def: "immediate care unit", note: "Fake. ICU stands for intensive care unit. Intensive, meaning the nursing is one-to-one and never stops.", lvl: 1 },
  { w: "vhs", say: "V H S", cat: "media", def: "video home standard", note: "Fake. VHS stands for Video Home System. JVC's tape ran longer than Betamax's, which is what won it.", lvl: 1 },
  { w: "iso", say: "I S O", cat: "business", def: "International Standards Organisation", note: "Fake. ISO does not stand for anything at all — the name comes from Greek <em>isos</em>, equal, chosen so that it reads the same in every language.", lvl: 1 },
  { w: "nasa", say: "nassa", cat: "space", def: "National Aeronautics and Space Agency", note: "Fake. NASA stands for National Aeronautics and Space Administration — <em>administration</em>. It is a civilian agency of government, but the A is for Administration.", lvl: 1 },
  { w: "fifa", say: "fee fah", cat: "business", def: "Federation of International Football Associations", note: "Fake. FIFA stands for Federation Internationale de Football Association. The name is French, and the association on the end is singular.", lvl: 1 },
  { w: "gchq", say: "G C H Q", cat: "military", def: "General Communications Headquarters", note: "Fake. GCHQ stands for Government Communications Headquarters. Government, not general — it sits under the Foreign Office at Cheltenham.", lvl: 1 },
  { w: "adsl", say: "A- D S L", cat: "telecoms", def: "asymmetric data subscriber line", note: "Fake. ADSL stands for asymmetric digital subscriber line — <em>digital</em>. Asymmetric because the download is faster than the upload.", lvl: 1 },
  { w: "hsbc", say: "H S B C", cat: "finance", def: "Hong Kong Savings Bank Corporation", note: "Fake. HSBC stands for Hongkong and Shanghai Banking Corporation, the two cities it was founded to trade between.", lvl: 1 },
  { w: "dvla", say: "D V L A-", cat: "transport", def: "Driver and Vehicle Licence Authority", note: "Fake. DVLA stands for Driver and Vehicle Licensing Agency. An agency in Swansea, and it licenses drivers rather than authorising them.", lvl: 1 },
  { w: "gcse", say: "G C S E", cat: "government", def: "General Certificate of School Education", note: "Fake. GCSE stands for General Certificate of Secondary Education — <em>secondary</em>. It replaced the O-level and the CSE in 1988.", lvl: 1 },
  { w: "hdmi", say: "H D M I", cat: "engineering", def: "high-definition media interface", note: "Fake. HDMI stands for High-Definition Multimedia Interface. Multimedia, because it carries the sound as well as the picture down one cable.", lvl: 1 },
  { w: "ptsd", say: "P T S D", cat: "medicine", def: "post-traumatic shock disorder", note: "Fake. PTSD stands for post-traumatic stress disorder — <em>stress</em>. The name replaced shell shock and combat fatigue in 1980.", lvl: 1 },
  { w: "bafta", say: "bafta", cat: "media", def: "British Academy of Film and Theatre Arts", note: "Fake. BAFTA stands for British Academy of Film and Television Arts — <em>television</em>. It was the British Film Academy until the television people were let in.", lvl: 1 },
  { w: "nafta", say: "nafta", cat: "business", def: "North American Free Trade Association", note: "Fake. NAFTA stands for North American Free Trade Agreement — <em>agreement</em>. It was a treaty, not a body, and it was replaced in 2020 by the USMCA.", lvl: 1 },
  { w: "covid", say: "covid", cat: "medicine", def: "coronavirus viral disease", note: "Fake. COVID stands for coronavirus disease 2019 — the number is part of the name, and the D is disease.", lvl: 1 },
  { w: "defra", say: "defra", cat: "government", def: "Department for Environment, Farming and Rural Affairs", note: "Fake. DEFRA stands for Department for Environment, Food and Rural Affairs — <em>food</em>. The department was built in 2001 around farming, food and the countryside.", lvl: 1 },
  { w: "tesco", say: "tesco", cat: "business", def: "the everyday store company", note: "Fake. TESCO is a portmanteau rather than an acronym: TES from the tea supplier T. E. Stockwell, CO from the founder Jack Cohen.", lvl: 1 },
  { w: "ofgem", say: "ofgem", cat: "government", def: "Office for Gas and Energy Management", note: "Fake. OFGEM stands for Office of Gas and Electricity Markets — <em>gas and electricity markets</em>. Every Of- regulator is named for the market it watches.", lvl: 1 },
  { w: "hazmat", say: "hazmat", cat: "policing", def: "hazard mitigation assessment team", note: "Fake. HAZMAT stands for hazardous materials, and nothing else. The label on the tanker is a warning, not a team.", lvl: 1 },
  { w: "nascar", say: "nascar", cat: "business", def: "National Association of Stock Car Racing", note: "Fake. NASCAR stands for National Association for Stock Car Auto Racing — <em>auto racing</em>. The full name is a mouthful, which is why nobody ever says it.", lvl: 1 },
  { w: "scotus", say: "scotus", cat: "government", def: "Senior Court of the United States", note: "Fake. SCOTUS stands for Supreme Court of the United States — <em>supreme</em>. The initialism was a telegraph shorthand long before it was a headline word.", lvl: 1 },
  /* ---------- level 1: invented acronyms, invented meanings ---------- */
  { w: "rhc", say: "R H C", cat: "medicine", def: "reflex health check", note: "Fake. RHC is real in medicine, but for right heart catheterisation — a catheter through a vein into the heart, not a reflex test.", coined: true, lvl: 1 },
  { w: "bcu", say: "B C U", cat: "medicine", def: "bone calcium uptake", note: "Fake. BCU is real twice over — a big close-up in a shooting script, and the British Canoe Union — but never a bone measurement.", coined: true, lvl: 1 },
  { w: "hbd", say: "H B D", cat: "telecoms", def: "home broadband device", note: "Fake. The trade abbreviation for home broadband is HBB, which is close enough to be irritating.", coined: true, lvl: 1 },
  { w: "tsi", say: "T S I", cat: "computing", def: "text service identifier", note: "Fake. TSI is real on the railways, for technical specifications for interoperability.", coined: true, lvl: 1 },
  { w: "zmp", say: "Z M P", cat: "computing", def: "zoned memory paging", note: "Fake. Zoned namespaces are real, and this abbreviation for them is not.", coined: true, lvl: 1 },
  { w: "kfl", say: "K F L", cat: "media", def: "keyframe layout", note: "Fake. KFL is a football league in Kerala and a language code in Cameroon, but never this.", coined: true, lvl: 1 },
  { w: "qrb", say: "Q R B", cat: "transport", def: "quiet route bypass", note: "Fake. QRB is real as a quality review board, and as the radio Q code for \"what is your distance?\"", coined: true, lvl: 1 },
  { w: "vgd", say: "V G D", cat: "engineering", def: "vapour gradient detector", note: "Fake. Vapour pressure gradients are real physics. This instrument is not.", coined: true, lvl: 1 },
  { w: "hrq", say: "H R Q", cat: "government", def: "housing register quota", note: "Fake. Housing registers are real, and are not run on quotas with initials.", coined: true, lvl: 1 },
  { w: "clip", say: "clip", cat: "policing", def: "Community Liaison and Incident Post", note: "Fake. CLIP is real in telephony, for calling line identification presentation: the thing that puts a number on your handset.", coined: true, lvl: 1 },
  { w: "snip", say: "snip", cat: "government", def: "Standard Notice of Inspection Period", note: "Fake. Geneticists do say <em>snip</em>, but they spell it SNP — a single nucleotide polymorphism.", coined: true, lvl: 1 },
  { w: "span", say: "span", cat: "engineering", def: "structural panel assessment note", note: "Fake. A span is the distance a beam crosses unsupported, and is a word rather than initials.", coined: true, lvl: 1 },
  { w: "quay", say: "key", cat: "marine", def: "quality assurance for yards", note: "Fake. A quay is where a ship ties up, it is pronounced \"key\", and it stands for nothing.", coined: true, lvl: 1 },
  { w: "swipe", say: "swipe", cat: "finance", def: "secure wireless payment entry", note: "Fake. The word came first and the expansion was fitted to it afterwards, which is usually the tell.", coined: true, lvl: 1 },
  { w: "stile", say: "stile", cat: "transport", def: "site transit inspection level entry", note: "Fake. A stile is the steps that let you over a fence, and the turnstile is its descendant.", coined: true, lvl: 1 },
  { w: "cobble", say: "cobble", cat: "engineering", def: "coastal bridge and bypass load evaluation", note: "Fake. Bridge load ratings are real and serious work, and they are recorded as numbers rather than as birds and stones.", coined: true, lvl: 1 },
  { w: "tiller", say: "tiller", cat: "science", def: "tidal lock level and entry record", note: "Fake. A tiller steers a boat, and does nothing else at all.", coined: true, lvl: 1 },
  { w: "ofpost", say: "off post", cat: "government", def: "Office of Postal Standards", note: "Fake. Britain has an Ofcom, an Ofgem and an Ofwat, but the post is regulated by Ofcom too.", coined: true, lvl: 1 },
  { w: "pantile", say: "pan tile", cat: "aviation", def: "panel terminal information and log equipment", note: "Fake. A pantile is an S-shaped roof tile, and has been since the seventeenth century.", coined: true, lvl: 1 },
  /* ---------- level 2: real acronyms, invented meanings ---------- */
  { w: "sad", say: "sad", cat: "medicine", def: "seasonal anxiety disorder", note: "Fake. SAD stands for seasonal affective disorder — <em>affective</em>, meaning it affects the mood. The treatment is a very bright lamp in the morning.", lvl: 2 },
  { w: "pcr", say: "P C R", cat: "science", def: "polymerase chain replication", note: "Fake. PCR stands for polymerase chain reaction — <em>reaction</em>. Each cycle doubles the DNA, so twenty cycles turn a trace into a million copies.", lvl: 2 },
  { w: "sql", say: "S Q L", cat: "computing", def: "standard query language", note: "Fake. SQL stands for Structured Query Language — <em>structured</em>. It began life at IBM as SEQUEL and had to be renamed after a trademark clash.", lvl: 2 },
  { w: "fob", say: "fob", cat: "marine", def: "freight on board", note: "Fake. FOB stands for free on board — the seller's cost stops at the ship's rail. Freight is what happens next.", lvl: 2 },
  { w: "oled", say: "oh led", cat: "engineering", def: "organic light-emitting display", note: "Fake. OLED stands for organic light-emitting diode — <em>diode</em>. It is a light-emitting diode made of an organic film, one pixel at a time.", lvl: 2 },
  { w: "isdn", say: "I S D N", cat: "telecoms", def: "integrated switched data network", note: "Fake. ISDN stands for integrated services digital network — <em>services</em>. It carried voice and data down the same copper pair, and it was the last word in speed in 1990.", lvl: 2 },
  { w: "rice", say: "rice", cat: "medicine", def: "rest, immobilise, compress, elevate", note: "Fake. RICE stands for rest, ice, compression, elevation. The ice is the whole reason the mnemonic is spelled that way.", lvl: 2 },
  { w: "fast", say: "fast", cat: "medicine", def: "face, arms, sight, time", note: "Fake. FAST stands for face, arms, speech, time — <em>speech</em>. Slurred speech is the third sign of a stroke, not blurred sight.", lvl: 2 },
  { w: "mash", say: "mash", cat: "medicine", def: "Medical Army Support Hospital", note: "Fake. MASH stands for Mobile Army Surgical Hospital — mobile is the point; it moved with the front.", lvl: 2 },
  { w: "saab", say: "sarb", cat: "transport", def: "Svenska Automobil Aktiebolaget", note: "Fake. SAAB stands for Svenska Aeroplan Aktiebolaget. The firm built aircraft first and cars only fifteen years later.", lvl: 2 },
  { w: "brat", say: "brat", cat: "medicine", def: "bananas, rice, apples, tea", note: "Fake. BRAT stands for bananas, rice, applesauce, toast — the bland diet for an upset stomach.", lvl: 2 },
  { w: "midi", say: "middy", cat: "media", def: "musical instrument data interface", note: "Fake. MIDI stands for Musical Instrument Digital Interface — <em>digital</em>. It carries note data, not sound, which is why a MIDI file is so small.", lvl: 2 },
  { w: "cmos", say: "see moss", cat: "engineering", def: "complementary memory-oxide semiconductor", note: "Fake. CMOS stands for complementary metal-oxide-semiconductor — <em>metal</em>. It is the process almost every chip in your house is made by.", lvl: 2 },
  { w: "swift", say: "swift", cat: "finance", def: "Secure Worldwide Interbank Financial Transfer", note: "Fake. SWIFT stands for Society for Worldwide Interbank Financial Telecommunication — <em>society</em>. It is a member-owned co-operative in Belgium, not a transfer mechanism.", lvl: 2 },
  { w: "libor", say: "lie bore", cat: "finance", def: "London Interbank Borrowing Rate", note: "Fake. LIBOR stands for London Interbank Offered Rate — <em>offered</em>. It was the rate banks said they would offer each other, which is how it came to be rigged.", lvl: 2 },
  { w: "norad", say: "nor add", cat: "military", def: "Northern Air Defence Command", note: "Fake. NORAD stands for North American Aerospace Defense Command, run jointly by the United States and Canada.", lvl: 2 },
  { w: "awacs", say: "ay wacks", cat: "aviation", def: "Airborne Warning and Command System", note: "Fake. AWACS stands for Airborne Warning and Control System — <em>control</em>. The aircraft directs the fight as well as spotting it.", lvl: 2 },
  { w: "potus", say: "poe tuss", cat: "government", def: "Principal Officer of the United States", note: "Fake. POTUS stands for President of the United States, from the old telegraphic codes; SCOTUS and FLOTUS are siblings.", lvl: 2 },
  { w: "flops", say: "flops", cat: "computing", def: "floating-point logic operations per second", note: "Fake. FLOPS stands for floating-point operations per second — no logic in it. It is how the speed of a supercomputer is quoted.", lvl: 2 },
  { w: "ofcom", say: "off com", cat: "government", def: "Office for Communications and Media", note: "Fake. OFCOM stands for Office of Communications — the name is deliberately plain.", lvl: 2 },
  { w: "epcot", say: "ep cot", cat: "business", def: "Experimental Planned City of Tomorrow", note: "Fake. EPCOT stands for Experimental Prototype Community of Tomorrow — <em>prototype community</em>. Walt Disney meant people to live there.", lvl: 2 },
  { w: "asean", say: "ah see ann", cat: "business", def: "Association of South East Asian Neighbours", note: "Fake. ASEAN stands for Association of Southeast Asian Nations — <em>nations</em>. Ten of them, and the association dates from 1967.", lvl: 2 },
  { w: "iupac", say: "you pack", cat: "science", def: "International Union of Practical and Applied Chemistry", note: "Fake. IUPAC stands for the International Union of Pure and Applied Chemistry — <em>pure</em>. It is the body that decides what every element and compound is called.", lvl: 2 },
  { w: "ebitda", say: "ee bit dah", cat: "finance", def: "earnings before interest, tax, dividends and amortisation", note: "Fake. EBITDA stands for earnings before interest, taxes, depreciation and amortisation — <em>depreciation</em>. Take out the depreciation and amortisation and the company looks healthier.", lvl: 2 },
  { w: "sitrep", say: "sit rep", cat: "military", def: "signals and troop report", note: "Fake. SITREP stands for situation report — what is happening, where, and how bad it is.", lvl: 2 },
  { w: "ecowas", say: "eck oh wass", cat: "business", def: "Economic Council of West African States", note: "Fake. ECOWAS stands for Economic Community of West African States. Modelled on the European Economic Community, down to the word community.", lvl: 2 },
  { w: "snotel", say: "snow tell", cat: "science", def: "snow observation and telemetry", note: "Fake. SNOTEL stands for snowpack telemetry — automated stations that weigh the snow on a mountain.", lvl: 2 },
  { w: "comsat", say: "com sat", cat: "telecoms", def: "combined military satellite", note: "Fake. COMSAT stands for Communications Satellite Corporation, created by Congress in 1962.", lvl: 2 },
  { w: "sunoco", say: "sun oh co", cat: "business", def: "Superior Northern Oil Company", note: "Fake. SUNOCO stands for Sun Oil Company. The name is just the two words run together.", lvl: 2 },
  { w: "navaid", say: "nav aid", cat: "aviation", def: "navigation and identification", note: "Fake. NAVAID stands for navigational aid — a beacon or a marker, and the word is one of aviation's oldest contractions.", lvl: 2 },
  { w: "jstars", say: "jay stars", cat: "military", def: "Joint Strategic Targeting and Reconnaissance System", note: "Fake. JSTARS stands for Joint Surveillance Target Attack Radar System. The radar in that enormous canoe under the fuselage watches the ground, not the sky.", lvl: 2 },
  { w: "comsec", say: "com sec", cat: "telecoms", def: "communications secrecy", note: "Fake. COMSEC stands for communications security — <em>security</em>. Secrecy is only part of it; the rest is making sure the message is genuine.", lvl: 2 },
  { w: "navsea", say: "nav see ah", cat: "marine", def: "Naval Sea Engineering Agency", note: "Fake. NAVSEA stands for Naval Sea Systems Command — <em>systems command</em>. It buys and maintains every ship the US Navy owns.", lvl: 2 },
  { w: "centcom", say: "sent com", cat: "military", def: "Central Combat Command", note: "Fake. CENTCOM stands for United States Central Command. The geographic command that covers the Middle East.", lvl: 2 },
  { w: "africom", say: "af ri com", cat: "military", def: "African Regional Command", note: "Fake. AFRICOM stands for United States Africa Command. It has been headquartered in Stuttgart since the day it was set up.", lvl: 2 },
  { w: "conrail", say: "con rail", cat: "transport", def: "Consolidated Railways", note: "Fake. CONRAIL stands for Consolidated Rail Corporation — <em>corporation</em>. It was assembled from six bankrupt railroads in 1976.", lvl: 2 },
  { w: "europol", say: "your oh pol", cat: "policing", def: "European Police Organisation", note: "Fake. EUROPOL is a contraction of European Police, not an acronym — the agency's actual name is the European Union Agency for Law Enforcement Cooperation.", lvl: 2 },
  { w: "milstar", say: "mill star", cat: "military", def: "military strategic and tactical array", note: "Fake. MILSTAR stands for Military Strategic and Tactical Relay — <em>relay</em>. The satellites relay traffic between commanders rather than storing it.", lvl: 2 },
  /* ---------- level 2: invented acronyms, invented meanings ---------- */
  { w: "sfd", say: "S F D", cat: "government", def: "site fire drill", note: "Fake. SFD is what a hundred American fire departments call themselves. It is not a kind of drill.", coined: true, lvl: 2 },
  { w: "tdn", say: "T D N", cat: "aviation", def: "terminal descent notice", note: "Fake. Top of descent is real and is written TOD. There is no TDN.", coined: true, lvl: 2 },
  { w: "hvpt", say: "H V P T", cat: "science", def: "high voltage proof test", note: "Fake. High-voltage proof testing is real work; engineers call it a hipot test and never this.", coined: true, lvl: 2 },
  { w: "wrmc", say: "W R M C", cat: "medicine", def: "ward records and medicine chart", note: "Fake. WRMC is real as the Western Regional Medical Command.", coined: true, lvl: 2 },
  { w: "cslt", say: "C S L T", cat: "telecoms", def: "cellular service line test", note: "Fake. The real cousin is SELT — a single-ended line test, which telephone engineers genuinely run.", coined: true, lvl: 2 },
  { w: "crest", say: "crest", cat: "aviation", def: "crew rest and standby time", note: "Fake. CREST is real in medicine, as the name of a form of scleroderma, and its letters are the five symptoms.", coined: true, lvl: 2 },
  { w: "whelk", say: "whelk", cat: "science", def: "wharf and estuary level keeper", note: "Fake. A whelk is a sea snail, and the word has never stood for anything.", coined: true, lvl: 2 },
  { w: "snarl", say: "snarl", cat: "policing", def: "scene attendance record log", note: "Fake. SNARL is real, but it belongs to South Norwood Animal Rescue and Liberty.", coined: true, lvl: 2 },
  { w: "clamp", say: "clamp", cat: "transport", def: "cargo lashing and mooring point", note: "Fake. Lashing points on a ship's deck are real fittings. They are numbered, not initialled.", coined: true, lvl: 2 },
  { w: "braid", say: "braid", cat: "computing", def: "broadband access interconnect directory", note: "Fake. A braid is a real part of a fibre-optic cable — the woven layer under the jacket.", coined: true, lvl: 2 },
  { w: "grouse", say: "grouse", cat: "military", def: "ground unit sensor", note: "Fake. Invented for this game — British forces do name kit after game birds, which is what makes it work.", coined: true, lvl: 2 },
  { w: "plover", say: "plover", cat: "marine", def: "pilot vessel radio", note: "Fake. There is a South African pilot vessel called Plover, which is as close as these letters get.", coined: true, lvl: 2 },
  { w: "sallow", say: "sallow", cat: "science", def: "soil, land level observation watch", note: "Fake. A sallow is a willow, and sallow is also what your face goes after a long winter indoors.", coined: true, lvl: 2 },
  { w: "hurdle", say: "hurdle", cat: "transport", def: "highway underpass rail depot level evaluation", note: "Fake. A hurdle was a portable fence panel long before it was something to jump over.", coined: true, lvl: 2 },
  { w: "kestrel", say: "kestrel", cat: "military", def: "key station relay", note: "Fake. Kestrel is a real name on radio equipment — a software-defined radio, a surveillance suite — but never as an acronym.", coined: true, lvl: 2 },
  { w: "jackdaw", say: "jackdaw", cat: "policing", def: "Joint Area Crime Knowledge Database and Warrants", note: "Fake. Police intelligence databases are real, and their names are drearier than this.", coined: true, lvl: 2 },
  { w: "grommet", say: "grommet", cat: "engineering", def: "ground mains measurement test", note: "Fake. A grommet is the ring that stops a cable chafing where it passes through a panel.", coined: true, lvl: 2 },
  { w: "shingle", say: "shingle", cat: "aviation", def: "Shipping Network for the Goods Load Exchange", note: "Fake. Shingle is the coarse gravel on a beach.", coined: true, lvl: 2 },
  /* ---------- level 3: real acronyms, invented meanings ---------- */
  { w: "cep", say: "C E P", cat: "military", def: "combat effectiveness percentage", note: "Fake. CEP stands for circular error probable — the radius the shell lands inside half the time.", lvl: 3 },
  { w: "dew", say: "dew", cat: "military", def: "detection and early warning", note: "Fake. DEW stands for Distant Early Warning. The DEW Line ran across the Arctic to watch for bombers coming over the pole.", lvl: 3 },
  { w: "rms", say: "R M S", cat: "marine", def: "registered merchant ship", note: "Fake. RMS stands for Royal Mail Ship. The Titanic carried the prefix because she carried the post.", lvl: 3 },
  { w: "adf", say: "A- D F", cat: "aviation", def: "airborne direction finder", note: "Fake. ADF stands for automatic direction finder — <em>automatic</em>. The needle finds the beacon on its own; the pilot only reads it.", lvl: 3 },
  { w: "sage", say: "sage", cat: "military", def: "Strategic Air Ground Environment", note: "Fake. SAGE stands for Semi-Automatic Ground Environment — the air defence computer that filled a building.", lvl: 3 },
  { w: "pace", say: "pace", cat: "policing", def: "Police and Criminal Enforcement Act", note: "Fake. PACE stands for Police and Criminal Evidence Act — <em>evidence</em>. The 1984 Act governs how the police gather it and how long they can hold you.", lvl: 3 },
  { w: "lasik", say: "lay sick", cat: "medicine", def: "laser in-situ keratotomy", note: "Fake. LASIK stands for laser-assisted in situ keratomileusis. Keratomileusis, from the Greek for carving the cornea, which is exactly what the laser does.", lvl: 3 },
  { w: "basic", say: "basic", cat: "computing", def: "Beginner's Algorithmic Symbolic Instruction Code", note: "Fake. BASIC stands for Beginner's All-purpose Symbolic Instruction Code — <em>all-purpose</em>. Kemeny and Kurtz wrote it at Dartmouth in 1964 for students who were not scientists.", lvl: 3 },
  { w: "pirep", say: "pie rep", cat: "aviation", def: "pilot information report", note: "Fake. PIREP stands for pilot report — what the crew saw out of the window, passed on to everyone behind them.", lvl: 3 },
  { w: "darpa", say: "dar pa", cat: "military", def: "Defence Applied Research Projects Agency", note: "Fake. DARPA stands for Defense Advanced Research Projects Agency — <em>advanced</em>. The agency exists to fund the research nobody else will.", lvl: 3 },
  { w: "scada", say: "ska dah", cat: "engineering", def: "supervisory control and data analysis", note: "Fake. SCADA stands for supervisory control and data acquisition — <em>acquisition</em>. The system acquires the data first and controls the plant second.", lvl: 3 },
  { w: "tacan", say: "tack ann", cat: "aviation", def: "target acquisition and navigation", note: "Fake. TACAN stands for tactical air navigation, the military beacon system that VOR pilots borrow the distance half of.", lvl: 3 },
  { w: "elint", say: "ell int", cat: "military", def: "electromagnetic intelligence", note: "Fake. ELINT stands for electronic intelligence — radar emissions, not messages, which is SIGINT's other half.", lvl: 3 },
  { w: "oscar", say: "oscar", cat: "telecoms", def: "orbiting satellite for communications and research", note: "Fake. OSCAR stands for Orbiting Satellite Carrying Amateur Radio, the ham radio satellites, first launched in 1961.", lvl: 3 },
  { w: "tiros", say: "tie ross", cat: "science", def: "telemetry and infrared observation satellite", note: "Fake. TIROS stands for Television Infrared Observation Satellite — <em>television</em>. The first weather satellite carried a television camera because that was the only way to send a picture.", lvl: 3 },
  { w: "candu", say: "can do", cat: "engineering", def: "Canadian Nuclear Development Unit", note: "Fake. CANDU stands for Canada Deuterium Uranium — the heavy-water reactor, named for its country and its fuel.", lvl: 3 },
  { w: "edvac", say: "ed vack", cat: "computing", def: "Electronic Digital Variable Automatic Computer", note: "Fake. EDVAC stands for Electronic Discrete Variable Automatic Computer — <em>discrete</em>. EDVAC was the discrete-variable machine that followed ENIAC.", lvl: 3 },
  { w: "sosus", say: "so suss", cat: "marine", def: "sound source underwater system", note: "Fake. SOSUS stands for sound surveillance system — <em>surveillance</em>. The undersea hydrophone chains listened for Soviet submarines for forty years.", lvl: 3 },
  { w: "wombat", say: "wombat", cat: "military", def: "weapon of medium bore anti-tank", note: "Fake. WOMBAT stands for Weapon of Magnesium, Battalion, Anti-Tank, which reads like a joke and is not.", lvl: 3 },
  { w: "univac", say: "you nee vack", cat: "computing", def: "universal variable automatic computer", note: "Fake. UNIVAC stands for Universal Automatic Computer, the first commercial computer sold in America.", lvl: 3 },
  { w: "shoran", say: "shore ann", cat: "military", def: "shore radio navigation", note: "Fake. SHORAN stands for short-range navigation. A wartime beacon system accurate enough to bomb by.", lvl: 3 },
  { w: "bitnet", say: "bit net", cat: "telecoms", def: "binary interchange terminal network", note: "Fake. BITNET stands for Because It's Time Network, named by a Yale administrator who had waited long enough.", lvl: 3 },
  { w: "tacamo", say: "tack ah mo", cat: "military", def: "tactical command and mobile operations", note: "Fake. TACAMO stands for Take Charge And Move Out, the aircraft that talks to submarines when everything else is gone.", lvl: 3 },
  { w: "masint", say: "mass int", cat: "military", def: "materials and signals intelligence", note: "Fake. MASINT stands for measurement and signature intelligence — the traces a thing leaves rather than what it says.", lvl: 3 },
  { w: "sigsaly", say: "sig sally", cat: "telecoms", def: "signal security analysis", note: "Fake. SIGSALY stood for nothing at all. It was a meaningless cover name; only the SIG marked it as Signal Corps work.", lvl: 3 },
  { w: "spectre", say: "specter", cat: "media", def: "Special Executive for Counter-intelligence, Terrorism, Revolution and Extortion", note: "Fake. SPECTRE stands for Special Executive for Counter-intelligence, Terrorism, Revenge and Extortion. Fleming spelled the name out in <em>Thunderball</em>.", lvl: 3 },
  { w: "teleran", say: "tel er an", cat: "aviation", def: "television relay air navigation", note: "Fake. TELERAN stands for Television Radar Air Navigation. RCA put the ground radar picture on a screen in the cockpit.", lvl: 3 },
  { w: "northag", say: "north ag", cat: "military", def: "Northern Allied Group", note: "Fake. NORTHAG stands for Northern Army Group — NATO's northern command in Germany until 1993.", lvl: 3 },
  { w: "autodin", say: "auto din", cat: "telecoms", def: "Automatic Data Interchange Network", note: "Fake. AUTODIN stands for Automatic Digital Network, the military's message switching system before email.", lvl: 3 },
  { w: "infosec", say: "in fo sec", cat: "computing", def: "infrastructure operations security", note: "Fake. INFOSEC stands for information security, plainly. The word has been in use since the 1970s.", lvl: 3 },
  { w: "southcom", say: "south com", cat: "military", def: "Southern Combat Command", note: "Fake. SOUTHCOM stands for United States Southern Command. The geographic command covering Latin America.", lvl: 3 },
  { w: "inmarsat", say: "in mar sat", cat: "telecoms", def: "International Marine Satellite", note: "Fake. INMARSAT stands for International Maritime Satellite Organisation — <em>maritime</em>. It began as a treaty organisation for ships and only later took on aircraft.", lvl: 3 },
  { w: "intelsat", say: "in tel sat", cat: "telecoms", def: "Integrated Telecommunications Satellite", note: "Fake. INTELSAT stands for International Telecommunications Satellite Organisation — <em>international</em>. It was a treaty organisation of member countries before it was a company.", lvl: 3 },
  { w: "unprofor", say: "you no for", cat: "military", def: "United Nations Provisional Force", note: "Fake. UNPROFOR stands for United Nations Protection Force. The UN deployment in the former Yugoslavia from 1992.", lvl: 3 },
  /* ---------- level 3: invented acronyms, invented meanings ---------- */
  { w: "cvn", say: "C V N", cat: "telecoms", def: "cable void notation", note: "Fake. CVN is a real US Navy hull code, for a nuclear-powered aircraft carrier.", coined: true, lvl: 3 },
  { w: "hzr", say: "H Z R", cat: "government", def: "hazard zone rating", note: "Fake. Hazard zones are real and are numbered — Zone 0, Zone 1, Zone 2 — not rated under initials.", coined: true, lvl: 3 },
  { w: "tpra", say: "T P R A-", cat: "finance", def: "Transaction Protection, Refund Agreement", note: "Fake. TPRA is real in business, but for third-party risk assessment.", coined: true, lvl: 3 },
  { w: "rowan", say: "rowan", cat: "science", def: "radar observation, wind and noise", note: "Fake. Wind profilers are real radar instruments, and they go by model numbers.", coined: true, lvl: 3 },
  { w: "pipit", say: "pipit", cat: "aviation", def: "pilot panel integration test", note: "Fake. The Parnall Pipit was a real naval fighter of 1928, named for the bird rather than for anything it stood for.", coined: true, lvl: 3 },
  { w: "dowel", say: "dowel", cat: "engineering", def: "drilling overhead works evaluation log", note: "Fake. A dowel is the peg that locks one piece of timber to another.", coined: true, lvl: 3 },
  { w: "flint", say: "flint", cat: "military", def: "field logistics intelligence note transfer", note: "Fake. FLINT is real in molecular biology, for fluorescence intensity.", coined: true, lvl: 3 },
  { w: "kipper", say: "kipper", cat: "media", def: "kiosk information, public programme exchange record", note: "Fake. KIPPER is real, and unkind: kids in parents' pockets eroding retirement savings.", coined: true, lvl: 3 },
  { w: "cinder", say: "cinder", cat: "science", def: "coastal incident, debris entry register", note: "Fake. CINDER is real at DARPA, for cyber insider threat.", coined: true, lvl: 3 },
  { w: "hobnail", say: "hob nail", cat: "marine", def: "Harbour Obstruction Boom and Net Anchorage Installation Log", note: "Fake. A hobnail is the stud in the sole of a boot.", coined: true, lvl: 3 },
  { w: "thistle", say: "thistle", cat: "military", def: "Tactical High-band Intercept and Signal Transmission Link Equipment", note: "Fake. Signals intercept kit is real and its names are classified, which is exactly what makes this one plausible.", coined: true, lvl: 3 },
  { w: "moorhen", say: "moor hen", cat: "science", def: "Moorland Rainfall and Hydrology Experiment Network", note: "Fake. Moorland hydrology stations are real, and they are named for the catchment rather than the bird.", coined: true, lvl: 3 },
  { w: "pennant", say: "pennant", cat: "marine", def: "Port Entry Navigation Notice, Annual Tides", note: "Fake. A pennant is a tapering flag, and in the Royal Navy a ship's number. Not this.", coined: true, lvl: 3 },
  { w: "quarrel", say: "quarrel", cat: "government", def: "quarterly audit record, regulation and enforcement log", note: "Fake. A quarrel is an argument, and also the short bolt fired from a crossbow.", coined: true, lvl: 3 },
  { w: "trawler", say: "trawler", cat: "science", def: "transit wave level estimation record", note: "Fake. Wave-level records are real oceanography. A trawler is a fishing boat.", coined: true, lvl: 3 },
  { w: "barnacle", say: "barnacle", cat: "transport", def: "Barge Navigation, Anchorage and Cargo Loading Entries", note: "Fake. Berth registers are real, and are kept by the harbourmaster under no name at all.", coined: true, lvl: 3 },
  { w: "windlass", say: "windless", cat: "marine", def: "waterway inspection, navigation data, lock and sluice survey", note: "Fake. A windlass raises an anchor, and on the canals it is the handle that works a lock.", coined: true, lvl: 3 }
];
